-- SQL data import for public.inventory_items and inventory_monitoring_snapshots from the Google Sheets workbook.
-- Run supabase/schema.sql first to create the required inventory and monitoring tables.
-- Masterfile provides item details, item numbers, beginning stock, and reorder points.
-- Inventory Monitoring provides current stock and historical purchase, sales, damage, and return totals.
-- Matching SKUs are updated, snapshots refreshed, new SKUs inserted, and unrelated rows preserved.
-- Re-running resets the monitoring baseline timestamp; resync only after the workbook includes intervening activity.
-- Existing IDs, units, variants, notes, and creation dates are preserved for matching items.
-- Source: https://docs.google.com/spreadsheets/d/1Z7Uku8-J5rvMqz4QsiUHXWlJFfnaycWjI_YxOyTP3kA/edit
-- Rows: 1,146. Current stock total: 1,159 units; beginning stock total: 2,254 units.

begin;

drop table if exists pg_temp.inventory_items_import;

create temporary table inventory_items_import (
  sku text primary key,
  item_number integer not null unique,
  name text not null,
  category text not null,
  description text not null,
  supplier_cost numeric(12,2) not null,
  supplier text not null,
  brand text not null,
  other_details text not null,
  unit_price numeric(12,2) not null,
  low_stock_threshold numeric(12,2) not null,
  begin_inventory numeric(12,2) not null,
  quantity numeric(12,2) not null,
  total_in_items numeric(12,2) not null,
  purchase_cost_amount numeric(30,2) not null,
  sales_quantity numeric(12,2) not null,
  cost_of_goods_sold numeric(30,2) not null,
  sales_revenue numeric(30,2) not null,
  profit numeric(30,2) not null,
  damage_quantity numeric(12,2) not null,
  damage_amount numeric(30,2) not null,
  returns_quantity numeric(12,2) not null,
  returns_amount numeric(30,2) not null,
  credit_purchase_quantity numeric(12,2) not null,
  credit_purchase_amount numeric(30,2) not null
) on commit preserve rows;


do $$
declare
  updated_count integer;
  inserted_count integer;
  snapshot_count integer;
begin
  if exists (
    select 1
    from public.inventory_items as existing
    join inventory_items_import as incoming
      on lower(btrim(existing.sku)) = lower(btrim(incoming.sku))
    group by lower(btrim(existing.sku))
    having count(*) > 1
  ) then
    raise exception 'More than one existing inventory row matches a Masterfile SKU; no items were changed.';
  end if;

  update public.inventory_items as existing
  set name = incoming.name,
      category = incoming.category,
      description = incoming.description,
      supplier_cost = incoming.supplier_cost,
      supplier = incoming.supplier,
      brand = incoming.brand,
      other_details = incoming.other_details,
      sku = incoming.sku,
      item_number = incoming.item_number,
      begin_inventory = incoming.begin_inventory,
      quantity = incoming.quantity,
      unit_price = incoming.unit_price,
      low_stock_threshold = incoming.low_stock_threshold,
      updated_at = now()
  from inventory_items_import as incoming
  where lower(btrim(existing.sku)) = lower(btrim(incoming.sku));
  get diagnostics updated_count = row_count;

    name, category, description, supplier, supplier_cost, brand, other_details,
    sku, item_number, begin_inventory, quantity, unit_price, low_stock_threshold
  )
  select incoming.name, incoming.category, incoming.description, incoming.supplier,
         incoming.supplier_cost, incoming.brand, incoming.other_details, incoming.sku,
         incoming.item_number, incoming.begin_inventory, incoming.quantity, incoming.unit_price, incoming.low_stock_threshold
  from inventory_items_import as incoming
  where not exists (
    select 1 from public.inventory_items as existing
    where lower(btrim(existing.sku)) = lower(btrim(incoming.sku))
  );
  get diagnostics inserted_count = row_count;

    item_id, total_in_items, purchase_cost_amount, sales_quantity, cost_of_goods_sold,
    sales_revenue, profit, damage_quantity, damage_amount, returns_quantity, returns_amount,
    credit_purchase_quantity, credit_purchase_amount, snapshot_updated_at
  )
  select existing.id, incoming.total_in_items, incoming.purchase_cost_amount, incoming.sales_quantity,
         incoming.cost_of_goods_sold, incoming.sales_revenue, incoming.profit, incoming.damage_quantity,
         incoming.damage_amount, incoming.returns_quantity, incoming.returns_amount,
         incoming.credit_purchase_quantity, incoming.credit_purchase_amount, now()
  from public.inventory_items as existing
  join inventory_items_import as incoming
    on lower(btrim(existing.sku)) = lower(btrim(incoming.sku))
  on conflict (item_id) do update set
    total_in_items = excluded.total_in_items,
    purchase_cost_amount = excluded.purchase_cost_amount,
    sales_quantity = excluded.sales_quantity,
    cost_of_goods_sold = excluded.cost_of_goods_sold,
    sales_revenue = excluded.sales_revenue,
    profit = excluded.profit,
    damage_quantity = excluded.damage_quantity,
    damage_amount = excluded.damage_amount,
    returns_quantity = excluded.returns_quantity,
    returns_amount = excluded.returns_amount,
    credit_purchase_quantity = excluded.credit_purchase_quantity,
    credit_purchase_amount = excluded.credit_purchase_amount,
    snapshot_updated_at = now();
  get diagnostics snapshot_count = row_count;
  raise notice 'Masterfile sync complete: % existing items updated, % new items inserted, % monitoring snapshots loaded.', updated_count, inserted_count, snapshot_count;
end
$$;

-- Verify the catalog, stock balances, and imported monitoring snapshot counts.
select count(*) as imported_sku_items,
       coalesce(sum(begin_inventory), 0) as beginning_inventory_units,
       coalesce(sum(quantity), 0) as current_stock_units,
       count(*) filter (where quantity > 0) as items_with_stock,
       count(item_number) as numbered_items
from public.inventory_items
where exists (
  select 1 from inventory_items_import as imported
  where lower(btrim(imported.sku)) = lower(btrim(inventory_items.sku))
);
select count(*) as monitoring_snapshots,
       coalesce(sum(sales_revenue), 0) as source_sales_revenue,
       coalesce(sum(profit), 0) as source_profit
from public.inventory_monitoring_snapshots as snapshot
where exists (
  select 1 from public.inventory_items as item
  join inventory_items_import as imported on lower(btrim(imported.sku)) = lower(btrim(item.sku))
  where item.id = snapshot.item_id
);

commit;
